// FleetMail design-only prototype: all records and state below are local mock data.
// There are intentionally no fetch calls, CRUD mutations, database queries, or live workflows.

type PageId =
  | 'dashboard'
  | 'vehicles'
  | 'vehicle-detail'
  | 'work-orders'
  | 'inspection'
  | 'schedule'
  | 'dispatch'
  | 'maintenance'
  | 'customers'
  | 'parts'
  | 'financials'
  | 'documents'
  | 'team'
  | 'settings';

type Status = 'In service' | 'Due soon' | 'Out of service' | 'Pending approval' | 'Scheduled' | 'In progress' | 'Ready to invoice' | 'Paid' | 'Low stock' | 'Available' | 'Overdue';

type Vehicle = {
  id: string;
  unit: string;
  make: string;
  model: string;
  year: number;
  vin: string;
  miles: string;
  status: Status;
  location: string;
  nextService: string;
  customer: string;
  initials: string;
  color: string;
};

type WorkOrder = {
  id: string;
  title: string;
  vehicle: string;
  unit: string;
  customer: string;
  status: Status;
  priority: 'Critical' | 'High' | 'Normal';
  technician: string;
  due: string;
  estimate: string;
  location: string;
};

